# New data for Yannik to infer the right formulae

using Oscar, GKMtools, CY5

G = gkm_5d_P2_111()
b = curve_class(G, Edge(1, 2))

d_max = 5

Omega = get_Omega_beta(G, [d * b for d in 1:d_max], 3; check_predictions=false)

Oscar.save(joinpath(@__DIR__, "P2_111_Omega.mrdi"), [Omega[d*b] for d in 1:d_max])

for d in 1:d_max
    println("Omega_$d:")
    println()
    println(Omega[d*b])
    println()
    println()
end

# Use this to load the results from the file
function load_P2_111_Omega(filename=joinpath(@__DIR__, "P2_111_Omega.mrdi"))
    return Oscar.load(filename)
end

